mapper.select:
    /* isry.couns.constt.mapper.BbserrListMapper.getTotalCount : 조회된 전체 데이터 갯수 */
    SELECT 
	    COUNT(*)
	FROM   AYE100 AA                   /* 사이버 상담게시글 */
	WHERE 1=1
	    AND NVL(DEL_YN, 'N') != 'Y';    /* 삭제여부 */
	                  /* 상태 : 접수 ==> 기본값*/
               /* 분류 : 채팅에러  ==> 기본값 */
            AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '01'     /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/
            AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD    = '01'         /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */

               /* 분류 : 그외 오류 */
            AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '01'     /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/
            AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD    = '02'         /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */



                      /* 상태 : 보류 */
               /* 분류 : 채팅에러 */
            AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '02'     /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/
            AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD    = '01'         /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */

               /* 분류 : 그외 오류 */
            AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '02'     /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/
            AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD    = '02'         /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */



                      /* 상태 : 완료 */
               /* 분류 : 채팅에러 */
            AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '03'     /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/
            AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD    = '01'         /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */


               /* 분류 : 그외 오류 */
            AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '03'     /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/
            AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD    = '02'         /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */





                 /* 검색어 조건 : 작성자 일 때 */
                     /* 검색어로 조회 */
            AND CC.FLNM LIKE '%' || #{strId} || '%'


                 /* 검색어 조건 : 제목 일 때 */
                     /* 검색어로 조회 */
            AND AA.BBSCTT_TTL_NM LIKE '%' || #{strId} || '%'


                 /* 검색어 조건 : 번호 일 때 */
                     /* 검색어로 조회 */
            AND AA.BBSCTT_ESNTAL_NO LIKE '%' || #{strId} || '%'


                 /* 검색어 조건 : 내용 일 때 */
                     /* 검색어로 조회 */
            AND AA.BBSCTT_CN LIKE '%' || #{strId} || '%'




        AND AA.FRST_REG_DT              >=      TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')
        AND AA.FRST_REG_DT              <       TO_DATE(#{END_DATE} || '000000', 'YYYYMMDDHH24MISS')+1

SELECT AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD /* 전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03)) */ , ( SELECT A.CMMNS_CD_VALUE_NM
FROM SAC100 A WHERE 1=1 AND CMMNS_CD_ID = 'DTPRSN_ERR_DCLR_ERR_SE_CD' /* 전산오류신고오류구분코드 */ AND A.CMMNS_CD_VALUE = AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD ) AS CL_TYPE_SE_CD /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */ , AA.DTPRSN_ERR_DCLR_ERR_SE_CD /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */ , DD.CMMNS_CD_VALUE_NM AS PRGRS_STTS_SE_CD /* 전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03)) */ , AA.BBSCTT_TTL_NM /* 제목 */ , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT /* 작성일 */ , AA.RDCNT_NOCS /* 조회 */ , AA.ATFINO /* 첨부 */ , AA.WRTR_NM /* 작성자 명 */ , AA.WRTR_NM || '(' || CC.USER_ID || ')' AS WRTR_ID /* 작성자 이름과 작성자 아이디 합치기. 이름(아이디) */ , CC.USER_ID /* 작성자 아이디 */ , AA.DEL_YN /* 삭제 여부 */ , AA.BBSCTT_ESNTAL_NO /* 게시글 고유 번호 : ex) 1950 */ , AA.BBSCTT_CN /* 게시글 내용 */ , AA.BBSCTT_TYPE_SE_CD /* 게시글 유형 구분 코드 : 전산오류 ==> 30번 */
FROM AYE100 AA /* 사이버 상담게시글 */ , SCA100 BB /* 종사자 테이블 */ , SAA200 CC /* 사용자 테이블 */ , SAC100 DD /* 공통코드 */ WHERE 1=1 AND AA.BBSCTT_TYPE_SE_CD = '30' AND BB.FLNM = AA.WRTR_NM /* 성명,작성자명 */ AND CC.ENFSN_NO = BB.ENFSN_NO /* 종사자번호 */ AND CC.USER_ID = #{userId} /* 로그인한 사용자 아이디 */
AND DD.CMMNS_CD_ID = 'DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD' /* 전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03)) */ AND DD.CMMNS_CD_VALUE = AA.DTPRSN_ERR_DCLR_ERR_SE_CD AND NVL(AA.DEL_YN, 'N') != 'Y' /* 삭제여부 */
/* 상태 : 접수 ==> 기본값*/ /* 분류 : 채팅에러 ==> 기본값 */ AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '01' /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/ AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD = '01' /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */
/* 분류 : 그외 오류 */ AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '01' /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/ AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD = '02' /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */
/* 상태 : 보류 */ /* 분류 : 채팅에러 */ AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '02' /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/ AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD = '01' /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */
/* 분류 : 그외 오류 */ AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '02' /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/ AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD = '02' /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */
/* 상태 : 완료 */ /* 분류 : 채팅에러 */ AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '03' /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/ AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD = '01' /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */
/* 분류 : 그외 오류 */ AND AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '03' /*전산오류신고진행상태구분코드(진행상태 ==> 접수(01),보류(02),완료(03))*/ AND AA.DTPRSN_ERR_DCLR_ERR_SE_CD = '02' /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */
/* 검색어 조건 : 작성자 일 때 */ /* 검색어로 조회 */ AND CC.FLNM LIKE '%' || #{strId} || '%'
/* 검색어 조건 : 제목 일 때 */ /* 검색어로 조회 */ AND AA.BBSCTT_TTL_NM LIKE '%' || #{strId} || '%'
/* 검색어 조건 : 번호 일 때 */ /* 검색어로 조회 */ AND AA.BBSCTT_ESNTAL_NO LIKE '%' || #{strId} || '%'
/* 검색어 조건 : 내용 일 때 */ /* 검색어로 조회 */ AND AA.BBSCTT_CN LIKE '%' || #{strId} || '%'
AND AA.FRST_REG_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS') AND AA.FRST_REG_DT < TO_DATE(#{END_DATE} || '000000', 'YYYYMMDDHH24MISS')+1
ORDER BY AA.BBSCTT_ESNTAL_NO DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY /* 페이징 처리 */

mapper.update:
/* isry.couns.constt.mapper.BbserrListMapper.updateBbserrDetail : 게시글 상세보기 수정하기 */
UPDATE AYE100 SET

    /* 게시글 제목 */
     BBSCTT_TTL_NM   =  #{BBSCTT_TTL_NM}

    /* 게시글 내용 */
   , BBSCTT_CN   =   #{BBSCTT_CN} 

WHERE    1   =   1
     AND BBSCTT_ESNTAL_NO    =   #{BBSCTT_ESNTAL_NO}     /*  게시글고유번호 */
     AND BBSCTT_TYPE_SE_CD   =   '30'                    /* 게시글유형구분코드 */
